\title{Density of the Quadratic-Irrational Restriction Class\\
in the Ratio Spectrum: The Topological Floor}
\author{Aristotle}
\date{2026-06-26}

\begin{document}
\maketitle

\begin{abstract}
For an integer $2\times 2$ matrix $M=\bigl(\begin{smallmatrix}p&q\\r&s\end{smallmatrix}\bigr)$
with nonzero determinant $D=ps-qr$, the linear-fractional (M\"obius) action
$M\cdot x=(px+q)/(rx+s)$ distorts the Lagrange constant
$k(x)=\liminf_{q\to\infty} q\,\lVert qx\rVert$ of a real number $x$. The
Lagarias--Shallit bounds confine the resulting \emph{ratio spectrum} to the
interval $[\,1/|D|,|D|\,]$, and a density conjecture asserts that the ratios
$k(Mx)/k(x)$ are dense in this interval as $x$ ranges over real quadratic
irrational badly approximable numbers. This paper isolates and rigorously
establishes the topological and algebraic floor of that program: (i) domain
density, that real quadratic irrationals are dense in $\R$, witnessed by the
explicit family $q+\sqrt2$ ($q\in\Q$); (ii) adjugate non-degeneracy and
inversion, that the inverse M\"obius map is well defined on irrationals and is a
left inverse of $M$; and (iii) image density, that the M\"obius image of the
quadratic-irrational locus is dense in $\R$. We also record the determinant
structure of the target interval and the action-theoretic identities (scaling
invariance, determinant multiplicativity, composition) that reduce the problem
to the primitive class of $M$, and via Smith normal form to the single family
$x\mapsto x/|D|$. All results are fully formalized. The remaining gap, the
analytic Lagrange-constant estimate, is isolated as future work.
\end{abstract}

\section{Introduction}

\subsection{The Lagrange constant}
Given a real number $x$, the \emph{Lagrange constant}
\[
k(x) \;=\; \liminf_{q\to\infty} \; q\,\lVert qx\rVert,
\qquad \lVert t\rVert = \dist(t,\Z),
\]
measures how badly $x$ resists rational approximation. A real number is
\emph{badly approximable} iff $k(x)>0$, equivalently iff its continued-fraction
partial quotients are bounded. The supremum of $k$ over irrationals is the
Hurwitz constant $1/\sqrt5$, attained at the golden ratio.

\subsection{The M\"obius action and the ratio spectrum}
The monoid of integer $2\times2$ matrices of nonzero determinant acts on $\R$ by
\[
M\cdot x \;=\; \frac{px+q}{rx+s}, \qquad M=\begin{pmatrix}p&q\\r&s\end{pmatrix}.
\]
For $\det M=\pm1$ the action edits only a finite head of the continued fraction,
so $k(Mx)=k(x)$. For general $D=\det M$, the Lagarias--Shallit theory yields
\begin{equation}\label{eq:LS}
\frac{1}{|D|} \;\le\; \frac{k(Mx)}{k(x)} \;\le\; |D|.
\end{equation}
The \emph{ratio spectrum} of $M$ is
\[
\Sigma(M) = \bigl\{\, k(Mx)/k(x) : x \text{ a real quadratic irrational badly approximable number}\,\bigr\}
\subseteq [\,1/|D|,|D|\,].
\]

\subsection{The density conjecture}
\begin{conjecture}[Density of the ratio spectrum]
For every primitive integer matrix $M$ with $\det M=D\ne0$, the set $\Sigma(M)$
is dense in $[\,1/|D|,|D|\,]$. Equivalently, for all reals $u<v$ with
$1/|D|\le u<v\le|D|$ there exists a real quadratic irrational $x$ with
$u<k(Mx)/k(x)<v$.
\end{conjecture}
Here \emph{primitive} means $\gcd(p,q,r,s)=1$, the natural normalization since
the M\"obius map is invariant under scaling all entries (Theorem~\ref{thm:scale}).

\subsection{Contribution}
The conjecture splits into an analytic stratum (control of $k$ along periodic
continued fractions) and a topological/algebraic stratum (richness of the sets
and non-degeneracy of the action). We rigorously establish the latter in full:
domain density (Theorem~\ref{thm:domaindense}), adjugate inversion
(Theorems~\ref{thm:adjden}--\ref{thm:adjinv}), image density
(Theorem~\ref{thm:imagedense}), closure (Theorem~\ref{thm:closure}), and the
determinant structure of Section~\ref{sec:det}. All statements are formally
verified.

\section{Preliminaries}

\begin{definition}[M\"obius action]
For integers $p,q,r,s$ and $x\in\R$,
$\mobius(p,q,r,s)(x) = \dfrac{p x+q}{r x+s}.$
\end{definition}

\begin{definition}[Quadratic-irrational locus]
A real number $x$ is a \emph{quadratic irrational}, written $\QuadIrr(x)$, iff
$x$ is irrational and there exist $a,b,c\in\Z$ with $a\ne0$ and
$a x^2 + b x + c = 0$.
\end{definition}

By Lagrange's theorem $\QuadIrr(x)$ holds iff the continued fraction of $x$ is
eventually periodic; every quadratic irrational is badly approximable.

\begin{lemma}[Anisotropy, \texttt{quadForm\_ne\_zero}]\label{lem:aniso}
Let $x$ be an irrational root of $a x^2+bx+c=0$ with $a\ne0$. Then for all
$(m,n)\ne(0,0)$,
\[
a m^2 - b m n + c n^2 \ne 0.
\]
\end{lemma}
\begin{proof}[Proof sketch]
If $n=0$ the value is $a m^2\ne0$. If $n\ne0$ and the form vanished, then the
identity $4a(am^2-bmn+cn^2)=(2am-bn)^2-(b^2-4ac)n^2$ together with
$(2ax+b)^2=(b^2-4ac)$ would give $(2ax+b)^2=\bigl(\tfrac{2am-bn}{n}\bigr)^2$,
hence $2ax+b\in\Q$. But $2ax+b$ is irrational when $x$ is and $a\ne0$.
Contradiction.
\end{proof}

\begin{lemma}[Image irrational, \texttt{irrational\_mobius}]\label{lem:irrmob}
If $x$ is irrational, $D=ps-qr\ne0$, and $rx+s\ne0$, then
$\mobius(p,q,r,s)(x)$ is irrational.
\end{lemma}
\begin{proof}[Proof sketch]
If $Mx=t\in\Q$ then $(p-tr)x=ts-q$; if $p-tr\ne0$ then $x\in\Q$, and if
$p-tr=0$ then $ts=q$ forces $D=0$. Both contradict the hypotheses.
\end{proof}

\begin{theorem}[Closure, \texttt{quadIrr\_mobius}]\label{thm:closure}
Let $x$ be a real quadratic irrational and $p,q,r,s\in\Z$ with $D=ps-qr\ne0$ and
$rx+s\ne0$. Then $\mobius(p,q,r,s)(x)$ is a real quadratic irrational.
\end{theorem}
\begin{proof}[Proof sketch]
Irrationality is Lemma~\ref{lem:irrmob}. Substituting the inverse relation into
$ax^2+bx+c=0$ and clearing $(p-ry)^2$ yields an integer quadratic in $y=Mx$ with
leading coefficient $A=as^2-bsr+cr^2$, which is nonzero by Lemma~\ref{lem:aniso}
applied to $(m,n)=(s,r)\ne(0,0)$.
\end{proof}

\section{Domain density}

\begin{theorem}[Explicit family, \texttt{quadIrr\_rat\_add\_sqrt\_two}]\label{thm:family}
For every $q\in\Q$, the number $q+\sqrt2$ is a real quadratic irrational.
\end{theorem}
\begin{proof}[Proof sketch]
$q+\sqrt2$ is irrational since $\sqrt2$ is. Writing $q=e/f$ with $f>0$, the
number satisfies $f^2 x^2 - 2ef\,x + (e^2-2f^2)=0$ with leading coefficient
$f^2\ne0$.
\end{proof}

\begin{theorem}[Domain density, \texttt{quadIrr\_dense}]\label{thm:domaindense}
For all reals $u<v$ there exists $x$ with $\QuadIrr(x)$ and $u<x<v$.
\end{theorem}
\begin{proof}[Proof sketch]
Choose a rational $q$ with $u-\sqrt2<q<v-\sqrt2$ (density of $\Q$); then
$x=q+\sqrt2$ is a quadratic irrational by Theorem~\ref{thm:family} and
$u<x<v$.
\end{proof}

\section{Adjugate inverse and image density}

For $M=\bigl(\begin{smallmatrix}p&q\\r&s\end{smallmatrix}\bigr)$ the adjugate is
$\adj M=\bigl(\begin{smallmatrix}s&-q\\-r&p\end{smallmatrix}\bigr)$, with
$\det(\adj M)=ps-qr$.

\begin{theorem}[Adjugate denominator, \texttt{mobius\_adjugate\_den\_ne\_zero}]\label{thm:adjden}
If $w$ is irrational and $ps-qr\ne0$, then $-r\,w+p\ne0$.
\end{theorem}
\begin{proof}[Proof sketch]
If $-rw+p=0$ and $r\ne0$ then $w=p/r\in\Q$; if $r=0$ then $p=0$, forcing
$ps-qr=0$. Both are contradictions.
\end{proof}

\begin{theorem}[Adjugate left inverse, \texttt{mobius\_adjugate\_left\_inverse}]\label{thm:adjinv}
If $ps-qr\ne0$ and $-r\,w+p\ne0$, then
$\mobius(p,q,r,s)\bigl(\mobius(s,-q,-r,p)(w)\bigr)=w.$
\end{theorem}
\begin{proof}[Proof sketch]
With $x=\dfrac{sw-q}{-rw+p}$,
\[
Mx=\frac{p(sw-q)+q(-rw+p)}{r(sw-q)+s(-rw+p)}
=\frac{(ps-qr)w}{ps-qr}=w,
\]
the common factor $\det M\ne0$ dividing out.
\end{proof}

\begin{theorem}[Image density, \texttt{mobius\_image\_dense}]\label{thm:imagedense}
Let $p,q,r,s\in\Z$ with $ps-qr\ne0$ and $u<v$ reals. Then there exists $x$ with
$\QuadIrr(x)$, $rx+s\ne0$, and $u<\mobius(p,q,r,s)(x)<v$.
\end{theorem}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:domaindense} pick a quadratic irrational $w\in(u,v)$ and set
$x=\mobius(s,-q,-r,p)(w)$, with denominator nonzero by
Theorem~\ref{thm:adjden}. Then $x$ is a quadratic irrational by
Theorem~\ref{thm:closure} (applied to $\adj M$, determinant $ps-qr\ne0$),
$rx+s\ne0$ by direct computation, and $Mx=w\in(u,v)$ by
Theorem~\ref{thm:adjinv}.
\end{proof}

\section{Determinant structure}\label{sec:det}

\begin{theorem}[Interval geometry]\label{thm:interval}
Let $D=ps-qr\ne0$. Then $1\le|D|$ \emph{(\texttt{one\_le\_absDet})};
$1/|D|\le1\le|D|$ \emph{(\texttt{one\_mem\_spectrum\_interval})};
$1/|D|\le|D|$ \emph{(\texttt{spectrum\_lower\_le\_upper})}; and
$(1/|D|)\cdot|D|=1$ \emph{(\texttt{spectrum\_endpoints\_mul})}.
\end{theorem}

\begin{theorem}[Scaling invariance, \texttt{mobius\_smul\_invariant}]\label{thm:scale}
For $k\ne0$ and all $x$, $\mobius(kp,kq,kr,ks)(x)=\mobius(p,q,r,s)(x)$.
\end{theorem}

Hence the ratio spectrum depends only on the primitive class of $M$.

\begin{theorem}[Determinant multiplicativity, \texttt{det\_mul}]\label{thm:detmul}
$(pp'+qr')(rq'+ss')-(pq'+qs')(rp'+sr')=(ps-qr)(p's'-q'r').$
\end{theorem}

\begin{theorem}[Composition, \texttt{mobius\_comp}]\label{thm:comp}
With nonvanishing inner and composed denominators,
\[
\mobius(p,q,r,s)\bigl(\mobius(p',q',r',s')(x)\bigr)
=\mobius(pp'+qr',\,pq'+qs',\,rp'+sr',\,rq'+ss')(x).
\]
\end{theorem}

\section{The Smith-normal-form reduction}
Combining Theorems~\ref{thm:scale} and~\ref{thm:comp} with the Smith normal form:
every primitive integer $M$ with $\det M=D$ admits $U,V\in\GL_2(\Z)$ with
$UMV=\diag(1,|D|)$, and since $\GL_2(\Z)$ acts by $k$-invariant M\"obius maps,
$\Sigma(M)=\Sigma(\diag(1,|D|))$. The problem collapses to the family
$x\mapsto x/D$, and density becomes: the values $k(x/D)/k(x)$ for quadratic
irrational $x$ are dense in $[1/D,D]$.

\section{Discussion and the remaining gap}
The results above form a complete, verified topological floor: dense domain
(Theorem~\ref{thm:domaindense}), invertible non-degenerate action
(Theorems~\ref{thm:adjden}--\ref{thm:adjinv}), dense image
(Theorem~\ref{thm:imagedense}), and a closed restriction class
(Theorem~\ref{thm:closure}); the determinant structure pins the ambient
interval. The remaining gap is analytic: image density controls $Mx$, not yet
$k(Mx)/k(x)$. Closing it requires a formal definition of $k$ via convergents,
the bound~\eqref{eq:LS} and its $\GL_2(\Z)$-invariance, and a continuity
argument inserting a single large partial quotient into a periodic expansion.

\section{Future work}
\begin{enumerate}
\item Define $k$ and prove $\GL_2(\Z)$-invariance and the
two-sided bound~\eqref{eq:LS} via Smith normal form.
\item Prove $UMV=\diag(1,|D|)$ for primitive $M$ and
$\Sigma(M)=\Sigma(\diag(1,|D|))$.
\item Show $\{k(x/D)/k(x)\}$ is dense in $[1/D,D]$ with endpoints approached but
not attained, via single-large-partial-quotient periodic continued fractions.
\end{enumerate}

